ACTIVE = ("pending", "processing")


def fail_extra_active_jobs(apps, schema_editor):
    """Keep each user's newest active job; fail any older one (scan-2 audit L5).

    The create view's row lock has always allowed only one, so this should
    match nothing. It exists so the constraint below can never abort the
    deploy on a row a non-view writer created. Failed as ``stale``: free of
    charge, exactly what the stale expiry would have done.
    """
    ScanJob = apps.get_model("plant_identification", "ScanJob")
    seen = set()
    extra = []
    for job_id, user_id in (
        ScanJob.objects.filter(status__in=ACTIVE)
        .order_by("user_id", "-created_at", "-pk")
        .values_list("pk", "user_id")
    ):
        if user_id in seen:
            extra.append(job_id)
        seen.add(user_id)
    if extra:
        ScanJob.objects.filter(pk__in=extra).update(
            status="failed", failure_reason="stale", finished_at=timezone.now()
        )


